import { products, categories, formatPrice } from './catalogue.js';

const esc = value => String(value).replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const findProduct = id => products.find(product => product.id === id);
const readStore = (key, fallback) => { try { return JSON.parse(localStorage.getItem(key)) ?? fallback; } catch { return fallback; } };
const storedBag = readStore('rahmeen-bag-v1', []);
let bag = Array.isArray(storedBag) ? storedBag.filter(item => { const p = findProduct(item?.id); return p && p.sizes.includes(item.size) && p.colors.some(c => c.name === item.color) && Number.isInteger(item.quantity) && item.quantity > 0 && item.quantity <= 99; }) : [];
const storedWishlist = readStore('rahmeen-wishlist-v1', []);
let wishlist = new Set(Array.isArray(storedWishlist) ? storedWishlist.filter(id => findProduct(id)) : []);
let initialized = false, toastTimer, searchTimer, returnFocus;
let shopState = {category:'All',size:'All',color:'All',fabric:'All',max:20000,sort:'featured'};
const heart = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/></svg>';
const arrow = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M4 12h15M13 5l7 7-7 7"/></svg>';
const bagKey = item => `${item.id}|${item.size}|${item.color}`;
const save = () => { try { localStorage.setItem('rahmeen-bag-v1',JSON.stringify(bag)); localStorage.setItem('rahmeen-wishlist-v1',JSON.stringify([...wishlist])); } catch {} updateCounters(); };

export function productCard(product) {
  const saved = wishlist.has(product.id);
  return `<article class="c-product-card" data-product-card="${product.id}">
    <div class="c-card-image"><a href="#/product/${product.id}" aria-label="Explore ${esc(product.name)}"><img src="${product.image}" alt="${esc(product.name)} — ${esc(product.subtitle)}" style="object-position:${product.position}" loading="lazy" width="600" height="800">${product.imageAlt?`<img class="c-card-alternate" src="${product.imageAlt}" alt="" style="object-position:${product.position}" loading="lazy" width="600" height="800">`:''}</a>
    <button class="c-heart ${saved?'is-saved':''}" data-commerce-action="wishlist" data-id="${product.id}" aria-label="${saved?'Remove':'Save'} ${esc(product.name)} ${saved?'from':'to'} wishlist" aria-pressed="${saved}">${heart}</button>
    <button class="c-quick-add" data-commerce-action="quick-add" data-id="${product.id}"><span>Quick add</span><span aria-hidden="true">+</span></button></div>
    <div class="c-card-meta"><div><a class="c-product-name" href="#/product/${product.id}">${esc(product.name)}</a><p>${esc(product.subtitle)}</p></div><span class="c-card-price">${formatPrice(product.price)}</span></div>
    <div class="c-swatches" aria-label="Available colours">${product.colors.map((color,i)=>`<button class="c-swatch ${i===0?'is-active':''}" style="--swatch:${color.hex}" title="${color.name}" aria-pressed="${i===0}" aria-label="View ${esc(product.name)} in ${color.name}" data-commerce-action="card-color" data-id="${product.id}" data-color="${color.name}"></button>`).join('')}<span class="c-color-name">${product.colors[0].name}</span></div>
  </article>`;
}

const filterOptions = (values, current) => values.map(value=>`<option value="${esc(value)}" ${value===current?'selected':''}>${esc(value)}</option>`).join('');
function matchingProducts() {
  const result = products.filter(p => (shopState.category==='All'||p.category===shopState.category)&&(shopState.size==='All'||p.sizes.includes(shopState.size))&&(shopState.color==='All'||p.colors.some(c=>c.name===shopState.color))&&(shopState.fabric==='All'||p.fabric===shopState.fabric)&&p.price<=shopState.max);
  if(shopState.sort==='price-low') result.sort((a,b)=>a.price-b.price);
  if(shopState.sort==='price-high') result.sort((a,b)=>b.price-a.price);
  if(shopState.sort==='name') result.sort((a,b)=>a.name.localeCompare(b.name));
  return result;
}
function shopResults() { const found=matchingProducts(); return found.length?found.map(productCard).join(''):`<div class="c-empty"><span class="c-empty-mark">✧</span><h2>No pieces found</h2><p>Try a different colour, size or price range.</p><button class="button c-solid" data-commerce-action="reset-filters">Clear filters</button></div>`; }
export function renderShop(category='All') {
  shopState={category:categories.includes(category)?category:'All',size:'All',color:'All',fabric:'All',max:20000,sort:'featured'};
  return `<section class="c-shop c-page"><div class="c-page-intro"><p class="eyebrow">THE RAHMEEN WARDROBE</p><h1>${shopState.category==='All'?'Find your <em>everyday extraordinary.</em>':esc(shopState.category)}</h1><p>Pieces to make your own. Discover thoughtful textures, joyful colour and effortless silhouettes.</p></div>
  <div class="c-shop-top"><span id="c-result-count" aria-live="polite">${matchingProducts().length} pieces</span><button class="c-filter-toggle" data-commerce-action="toggle-filters" aria-expanded="false" aria-controls="c-filters">Filters <span aria-hidden="true">+</span></button><label class="c-sort-label">Sort by <select name="sort" data-shop-filter="sort"><option value="featured">Featured</option><option value="price-low">Price: low to high</option><option value="price-high">Price: high to low</option><option value="name">Name: A to Z</option></select></label></div>
  <div class="c-shop-layout"><aside class="c-filters" id="c-filters" aria-label="Filter products"><div class="c-filter-heading"><h2>Refine your edit</h2><button data-commerce-action="reset-filters">Clear all</button></div>
  <label>Collection<select data-shop-filter="category">${filterOptions(['All',...categories],shopState.category)}</select></label>
  <label>Size<select data-shop-filter="size">${filterOptions(['All','XS','S','M','L','XL','One Size','Unstitched'],'All')}</select></label>
  <label>Colour<select data-shop-filter="color">${filterOptions(['All',...new Set(products.flatMap(p=>p.colors.map(c=>c.name)))],'All')}</select></label>
  <label>Fabric<select data-shop-filter="fabric">${filterOptions(['All','Cotton','Lawn','Linen','Organza'],'All')}</select></label>
  <label>Maximum price <output id="c-price-value">${formatPrice(20000)}</output><input type="range" min="5000" max="20000" step="50" value="20000" data-shop-filter="max" aria-label="Maximum price in Pakistani rupees"></label><p class="c-filter-note">A wardrobe for every version of you.</p></aside>
  <div class="c-product-grid c-shop-grid" id="c-shop-results">${shopResults()}</div></div></section>`;
}

export function renderProduct(id) {
  const p=findProduct(id); if(!p) return `<section class="c-page c-empty"><h1>This piece is not in our edit.</h1><p>Explore the collection to find something you love.</p><a class="button c-solid" href="#/shop">Explore the collection ${arrow}</a></section>`;
  return `<section class="c-product-page c-page" data-detail-id="${p.id}"><nav class="c-breadcrumb" aria-label="Breadcrumb"><a href="#/">Home</a><span>/</span><a href="#/shop/${encodeURIComponent(p.category)}">${p.category}</a><span>/</span><span>${esc(p.name)}</span></nav>
  <div class="c-product-layout"><div class="c-gallery"><div class="c-gallery-main"><img id="c-main-photo" src="${p.image}" alt="${esc(p.name)} — full view" style="object-position:${p.position}" width="900" height="1200"><span id="c-gallery-caption">Full view</span></div><div class="c-gallery-thumbs"><button class="is-active" data-commerce-action="gallery" data-view="full" aria-label="Show full view" aria-pressed="true"><img src="${p.image}" alt="" style="object-position:${p.position}"></button><button data-commerce-action="gallery" data-view="detail" aria-label="${p.imageAlt?'Show alternate view':'Show closer crop of the same photograph'}" aria-pressed="false"><img class="${p.imageAlt?'':'c-detail-crop'}" src="${p.imageAlt||p.image}" alt="" style="object-position:${p.position}"></button><span>${p.imageAlt?'Full & alternate views':'Full view & a closer look'}</span></div></div>
  <div class="c-product-info"><p class="eyebrow">${p.category.toUpperCase()}</p><h1>${esc(p.name)}</h1><p class="c-product-subtitle">${esc(p.subtitle)}</p><p class="c-detail-price">${formatPrice(p.price)}</p><p class="c-product-description">${esc(p.description)}</p>
  <div class="c-choice"><span>Colour: <strong id="c-selected-color">${p.colors[0].name}</strong></span><div class="c-detail-colors">${p.colors.map((c,i)=>`<button class="c-swatch ${i===0?'is-active':''}" style="--swatch:${c.hex}" aria-label="${c.name}" aria-pressed="${i===0}" data-commerce-action="detail-color" data-color="${c.name}"></button>`).join('')}</div><small>Colour options are part of this demo catalogue; photography is representative.</small></div>
  <div class="c-choice"><div class="c-choice-heading"><span>${p.sizes.length===1?'Format':'Select size'}</span>${p.sizes.length>1?'<button class="c-text-button" data-commerce-action="size-guide">Size guide ↗</button>':''}</div><div class="c-size-buttons" id="c-size-choice" role="group" aria-label="Choose a size">${p.sizes.map(size=>`<button data-commerce-action="detail-size" data-size="${size}" aria-pressed="${p.sizes.length===1}" class="${p.sizes.length===1?'is-active':''}">${size}</button>`).join('')}</div><p class="c-form-error" id="c-size-error" role="alert"></p></div>
  <div class="c-add-row"><div class="c-quantity" aria-label="Quantity"><button data-commerce-action="detail-minus" aria-label="Decrease quantity">−</button><output id="c-detail-quantity">1</output><button data-commerce-action="detail-plus" aria-label="Increase quantity">+</button></div><button class="button c-solid c-add-detail" data-commerce-action="add-detail" data-id="${p.id}">Add to bag ${arrow}</button><button class="c-detail-heart ${wishlist.has(p.id)?'is-saved':''}" data-commerce-action="wishlist" data-id="${p.id}" aria-label="Save ${esc(p.name)} to wishlist" aria-pressed="${wishlist.has(p.id)}">${heart}</button></div>
  <p class="c-purchase-note">A considered piece. A wardrobe all your own.</p><div class="c-accordions"><details open><summary>The details <span>+</span></summary><ul>${p.details.map(item=>`<li>${esc(item)}</li>`).join('')}</ul></details><details><summary>Care, with love <span>+</span></summary><p>${esc(p.care)}</p></details><details><summary>Delivery & returns <span>+</span></summary><p>This is an interactive storefront preview. Shipping, returns and payment services are not connected; no order or payment will be processed.</p></details></div></div></div>
  <section class="c-related"><div class="c-related-heading"><div><p class="eyebrow">A LITTLE MORE TO LOVE</p><h2>Beautiful <em>together.</em></h2></div><a href="#/shop" class="c-text-button">Discover all ${arrow}</a></div><div class="c-product-grid">${products.filter(item=>item.id!==p.id).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,4).map(productCard).join('')}</div></section></section>`;
}
export function renderWishlist() {
  const saved=products.filter(p=>wishlist.has(p.id));
  return `<section class="c-page c-wishlist-page"><div class="c-page-intro"><p class="eyebrow">THE PIECES YOU LOVE</p><h1>Your <em>wishlist.</em></h1><p>A little collection of things that feel like you. <span class="c-wishlist-count"><span data-wishlist-count>${saved.length}</span> saved.</span></p></div><div class="c-product-grid" id="c-wishlist-results">${saved.length?saved.map(productCard).join(''):`<div class="c-empty">${heart}<h2>Make room for a little love.</h2><p>Tap the heart on any piece to save it here for later.</p><a class="button c-solid" href="#/shop">Find your favourites ${arrow}</a></div>`}</div></section>`;
}

function updateCounters() {
  const count=bag.reduce((total,item)=>total+item.quantity,0);
  document.querySelectorAll('[data-bag-count]').forEach(el=>el.textContent=count);
  document.querySelectorAll('[data-wishlist-count]').forEach(el=>el.textContent=wishlist.size);
  document.querySelectorAll('[data-commerce-action="wishlist"]').forEach(el=> { const saved=wishlist.has(el.dataset.id); el.classList.toggle('is-saved',saved);el.setAttribute('aria-pressed',String(saved));el.setAttribute('aria-label',`${saved?'Remove':'Save'} ${findProduct(el.dataset.id)?.name||'piece'} ${saved?'from':'to'} wishlist`); });
}
function toast(message) { const el=document.getElementById('c-toast'); if(!el)return;el.textContent=message;el.classList.add('is-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('is-visible'),3200); }
function openDialog(id,html,stacked=false) {
  const hasOpenDialog=Boolean(document.querySelector('.c-dialog[open]'));
  if(!hasOpenDialog)returnFocus=document.activeElement;
  if(!stacked)document.querySelectorAll('.c-dialog[open]').forEach(dialog=>dialog.close());
  const dialog=document.getElementById(id);dialog.innerHTML=html;dialog.showModal();document.body.classList.add('c-dialog-open');
}
function closeDialogs() { document.querySelectorAll('.c-dialog[open]').forEach(dialog=>dialog.close()); }
const dialogHeader = (title,id) => `<div class="c-dialog-heading"><h2 id="${id}">${title}</h2><button class="c-close" data-commerce-action="close" aria-label="Close dialog">×</button></div>`;
const bagSubtotal = () => bag.reduce((sum,item)=>sum+findProduct(item.id).price*item.quantity,0);
function bagContents() {
  return `${dialogHeader(`Your bag <span>(${bag.reduce((sum,item)=>sum+item.quantity,0)})</span>`,'c-bag-title')}${bag.length?`<div class="c-bag-items">${bag.map(item=>{const p=findProduct(item.id); return `<article class="c-bag-item"><a href="#/product/${p.id}" data-commerce-action="dialog-link"><img src="${p.image}" alt="${esc(p.name)}" style="object-position:${p.position}"></a><div><a href="#/product/${p.id}" data-commerce-action="dialog-link" class="c-bag-name">${esc(p.name)}</a><p>${item.color} / ${item.size}</p><span class="c-bag-item-price">${formatPrice(p.price)}</span><div class="c-bag-item-controls"><div class="c-quantity"><button data-commerce-action="bag-minus" data-key="${bagKey(item)}" aria-label="Decrease ${esc(p.name)} quantity">−</button><span>${item.quantity}</span><button data-commerce-action="bag-plus" data-key="${bagKey(item)}" aria-label="Increase ${esc(p.name)} quantity">+</button></div><button class="c-text-button" data-commerce-action="bag-remove" data-key="${bagKey(item)}" aria-label="Remove ${esc(p.name)} from bag">Remove</button></div></div></article>`;}).join('')}</div><div class="c-bag-footer"><div class="c-subtotal"><span>Subtotal</span><strong>${formatPrice(bagSubtotal())}</strong></div><p>Shipping is not calculated in this preview.</p><button class="button c-solid" data-commerce-action="checkout">Review bag ${arrow}</button><span class="c-demo-note">Demo storefront · No orders or payments are processed.</span><button class="c-continue" data-commerce-action="close">Continue exploring</button></div>`:`<div class="c-empty c-empty-bag"><span class="c-empty-mark">✧</span><h3>A little room for something lovely.</h3><p>Your bag is waiting for its first piece.</p><a href="#/shop" class="button c-solid" data-commerce-action="dialog-link">Explore the collection ${arrow}</a></div>`}`;
}
function openBag() { openDialog('c-bag-dialog',bagContents()); }
function renderBagPreservingFocus(action,key) { const dialog=document.getElementById('c-bag-dialog'); dialog.innerHTML=bagContents(); const next=[...dialog.querySelectorAll(`[data-commerce-action="${action}"]`)].find(el=>el.dataset.key===key); (next||dialog.querySelector('.c-close')).focus(); }
function searchResults(query) {
  const q=query.trim().toLocaleLowerCase();const matches=q?products.filter(p=>`${p.name} ${p.category} ${p.fabric} ${p.colors.map(c=>c.name).join(' ')}`.toLocaleLowerCase().includes(q)):products.slice(0,4);
  return `<p class="c-search-count">${q?`${matches.length} ${matches.length===1?'piece':'pieces'} found`:'A few pieces to start with'}</p>${matches.length?matches.map(p=>`<a href="#/product/${p.id}" class="c-search-result" data-commerce-action="dialog-link"><img src="${p.image}" alt="" style="object-position:${p.position}"><span><strong>${esc(p.name)}</strong><small>${esc(p.subtitle)}</small><span>${formatPrice(p.price)}</span></span>${arrow}</a>`).join(''):`<div class="c-empty"><h3>No matches just yet.</h3><p>Try “cotton”, “sage” or “festive”.</p></div>`}`;
}
function openSearch() {clearTimeout(searchTimer);openDialog('c-search-dialog',`${dialogHeader('Find something <em>you love.</em>','c-search-title')}<label class="c-search-input"><span class="sr-only">Search the collection</span><input id="c-search-field" type="search" placeholder="Search pieces, colours, fabrics…" autocomplete="off" autofocus><span aria-hidden="true">↗</span></label><div class="c-search-results" id="c-search-results" aria-live="polite">${searchResults('')}</div>`);document.getElementById('c-search-field').focus();}
function openQuickAdd(id,color) {const p=findProduct(id); if(!p)return; const chosen=p.colors.some(c=>c.name===color)?color:p.colors[0].name;openDialog('c-quick-dialog',`${dialogHeader('Make it yours','c-quick-title')}<div class="c-quick-product"><img src="${p.image}" alt="${esc(p.name)}" style="object-position:${p.position}"><div><p class="eyebrow">${p.category}</p><h3>${esc(p.name)}</h3><p>${formatPrice(p.price)}</p></div></div><form id="c-quick-form" data-id="${p.id}"><label class="c-field-label">Colour<select name="color">${p.colors.map(c=>`<option ${c.name===chosen?'selected':''}>${c.name}</option>`).join('')}</select></label><label class="c-field-label">${p.sizes.length===1?'Format':'Select size'}<select name="size" required>${p.sizes.length>1?'<option value="">Choose your size</option>':''}${p.sizes.map(size=>`<option>${size}</option>`).join('')}</select></label>${p.sizes.length>1?'<button type="button" class="c-text-button c-quick-guide" data-commerce-action="size-guide">View size guide ↗</button>':''}<button type="submit" class="button c-solid">Add to bag ${arrow}</button></form>`);}
function addToBag(id,size,color,quantity=1) {const p=findProduct(id);if(!p||!p.sizes.includes(size)||!p.colors.some(c=>c.name===color))return;const existing=bag.find(item=>bagKey(item)===bagKey({id,size,color}));if(existing)existing.quantity=Math.min(99,existing.quantity+quantity);else bag.push({id,size,color,quantity:Math.min(quantity,99)});save();toast(`${p.name} added to your bag`);}
function showSizeGuide() {openDialog('c-guide-dialog',`${dialogHeader('Find your fit','c-guide-title')}<p class="c-guide-intro">An illustrative guide for this demo collection. Measurements below are body measurements in inches.</p><div class="c-table-wrap"><table><caption class="sr-only">Body measurements by clothing size, in inches</caption><thead><tr><th>Size</th><th>Bust</th><th>Waist</th><th>Hip</th></tr></thead><tbody>${[['XS',32,26,35],['S',34,28,37],['M',36,30,39],['L',38,32,41],['XL',40,34,43]].map(row=>`<tr>${row.map((cell,i)=>i===0?`<th scope="row">${cell}</th>`:`<td>${cell}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="c-guide-intro">Measure around the fullest part of your bust and hips, and your natural waist. If you prefer a more relaxed fit, choose the larger size.</p><button class="button c-solid" data-commerce-action="close">Back to your piece</button>`,document.getElementById('c-quick-dialog').open);}
function updateShop() {const results=document.getElementById('c-shop-results');if(!results)return;results.innerHTML=shopResults();document.getElementById('c-result-count').textContent=`${matchingProducts().length} pieces`;document.getElementById('c-price-value').textContent=formatPrice(shopState.max);document.querySelector('.c-shop .c-page-intro h1').innerHTML=shopState.category==='All'?'Find your <em>everyday extraordinary.</em>':esc(shopState.category);history.replaceState(null,'',shopState.category==='All'?'#/shop':`#/shop/${encodeURIComponent(shopState.category)}`);}
function handleClick(event) {
  const target=event.target.closest('[data-commerce-action]'); if(!target)return;
  const action=target.dataset.commerceAction,id=target.dataset.id;
  if(action==='close')target.closest('.c-dialog')?.close();
  if(action==='dialog-link')closeDialogs();
  if(action==='open-bag')openBag();
  if(action==='open-search')openSearch();
  if(action==='wishlist') { const p=findProduct(id);if(!p)return;wishlist.has(id)?wishlist.delete(id):wishlist.add(id);save();toast(wishlist.has(id)?`${p.name} saved to your wishlist`:`${p.name} removed from your wishlist`);const results=document.getElementById('c-wishlist-results');if(results){const saved=products.filter(p=>wishlist.has(p.id));if(saved.length){results.innerHTML=saved.map(productCard).join('');results.querySelector('[data-commerce-action=wishlist]')?.focus();}else{document.querySelector('.c-wishlist-page').outerHTML=renderWishlist();document.querySelector('.c-wishlist-page .c-empty a')?.focus();}}}
  if(action==='card-color') {const card=target.closest('[data-product-card]');card.dataset.selectedColor=target.dataset.color;card.querySelectorAll('.c-swatch').forEach(el=>{el.classList.toggle('is-active',el===target);el.setAttribute('aria-pressed',String(el===target));});card.querySelector('.c-color-name').textContent=target.dataset.color;}
  if(action==='quick-add')openQuickAdd(id,target.closest('[data-product-card]')?.dataset.selectedColor);
  if(action==='size-guide')showSizeGuide();
  if(action==='detail-color') {document.getElementById('c-selected-color').textContent=target.dataset.color;document.querySelectorAll('.c-detail-colors .c-swatch').forEach(el=>{el.classList.toggle('is-active',el===target);el.setAttribute('aria-pressed',String(el===target));});}
  if(action==='detail-size') {document.querySelectorAll('#c-size-choice button').forEach(el=>{el.classList.toggle('is-active',el===target);el.setAttribute('aria-pressed',String(el===target));});document.getElementById('c-size-error').textContent='';}
  if(action==='detail-minus'||action==='detail-plus') {const output=document.getElementById('c-detail-quantity');output.textContent=Math.max(1,Math.min(99,Number(output.textContent)+(action==='detail-plus'?1:-1)));}
  if(action==='add-detail') {const size=document.querySelector('#c-size-choice .is-active')?.dataset.size;if(!size){document.getElementById('c-size-error').textContent='Please choose your size first.';document.querySelector('#c-size-choice button')?.focus();return;}addToBag(id,size,document.getElementById('c-selected-color').textContent,Number(document.getElementById('c-detail-quantity').textContent));}
  if(action==='gallery') {const detail=target.dataset.view==='detail',photo=document.getElementById('c-main-photo'),p=findProduct(target.closest('[data-detail-id]').dataset.detailId);photo.src=detail&&p.imageAlt?p.imageAlt:p.image;photo.classList.toggle('is-cropped',detail&&!p.imageAlt);photo.alt=`${p.name} — ${detail?(p.imageAlt?'alternate view':'closer crop of the same photograph'):'full view'}`;document.getElementById('c-gallery-caption').textContent=detail?(p.imageAlt?'Alternate view':'Closer look · cropped view'):'Full view';document.querySelectorAll('.c-gallery-thumbs button').forEach(el=>{el.classList.toggle('is-active',el===target);el.setAttribute('aria-pressed',String(el===target));});}
  if(action==='bag-plus'||action==='bag-minus'||action==='bag-remove') {const key=target.dataset.key,item=bag.find(item=>bagKey(item)===key);if(!item)return;if(action==='bag-remove'||action==='bag-minus'&&item.quantity===1)bag=bag.filter(row=>bagKey(row)!==key);else item.quantity=Math.min(99,item.quantity+(action==='bag-plus'?1:-1));save();renderBagPreservingFocus(action,key);}
  if(action==='checkout')openDialog('c-review-dialog',`${dialogHeader('Your collection, reviewed.','c-review-title')}<p class="c-guide-intro">This is a storefront demo. Your bag is saved on this device, but no order will be placed and no payment will be collected.</p><div class="c-review-items">${bag.map(item=>`<div><span>${esc(findProduct(item.id).name)}<small>${item.color} / ${item.size} · Qty ${item.quantity}</small></span><strong>${formatPrice(findProduct(item.id).price*item.quantity)}</strong></div>`).join('')}</div><div class="c-subtotal"><span>Product subtotal</span><strong>${formatPrice(bagSubtotal())}</strong></div><p class="c-guide-intro">Delivery and payment options will be available when the live store launches.</p><button class="button c-solid" data-commerce-action="open-bag">Back to your bag</button>`);
  if(action==='toggle-filters'){const filter=document.getElementById('c-filters'),isOpen=filter.classList.toggle('is-open');target.setAttribute('aria-expanded',String(isOpen));}
  if(action==='reset-filters'){shopState={category:'All',size:'All',color:'All',fabric:'All',max:20000,sort:'featured'};document.querySelectorAll('[data-shop-filter]').forEach(el=>el.value=shopState[el.dataset.shopFilter]);updateShop();}
}
export function initCommerce() {
  if(!initialized){initialized=true;
    const host=document.createElement('div');host.id='c-commerce-host';host.innerHTML=`<dialog class="commerce-dialog c-dialog c-bag-dialog" id="c-bag-dialog" aria-labelledby="c-bag-title"></dialog><dialog class="commerce-dialog c-dialog c-search-dialog" id="c-search-dialog" aria-labelledby="c-search-title"></dialog><dialog class="commerce-dialog c-dialog c-quick-dialog" id="c-quick-dialog" aria-labelledby="c-quick-title"></dialog><dialog class="commerce-dialog c-dialog c-guide-dialog" id="c-guide-dialog" aria-labelledby="c-guide-title"></dialog><dialog class="commerce-dialog c-dialog c-review-dialog" id="c-review-dialog" aria-labelledby="c-review-title"></dialog><div id="c-toast" class="c-toast" role="status" aria-live="polite"></div>`;document.body.appendChild(host);
    document.addEventListener('click',handleClick);
    document.addEventListener('change',event=>{const field=event.target.closest('[data-shop-filter]');if(field){shopState[field.dataset.shopFilter]=field.dataset.shopFilter==='max'?Number(field.value):field.value;updateShop();}});
    document.addEventListener('input',event=>{if(event.target.id==='c-search-field'){clearTimeout(searchTimer);const query=event.target.value;searchTimer=setTimeout(()=>{const results=document.getElementById('c-search-results');if(results)results.innerHTML=searchResults(query);},180);}if(event.target.dataset.shopFilter==='max'){shopState.max=Number(event.target.value);updateShop();}});
    document.addEventListener('submit',event=>{if(event.target.id!=='c-quick-form')return;event.preventDefault();const form=event.target;if(!form.reportValidity())return;addToBag(form.dataset.id,form.elements.size.value,form.elements.color.value);closeDialogs();});
    document.querySelectorAll('.c-dialog').forEach(dialog=>{dialog.addEventListener('click',event=>{if(event.target===dialog){const rect=dialog.getBoundingClientRect();if(event.clientX<rect.left||event.clientX>rect.right||event.clientY<rect.top||event.clientY>rect.bottom)dialog.close();}});dialog.addEventListener('close',()=>{if(!document.querySelector('.c-dialog[open]')){document.body.classList.remove('c-dialog-open');if(returnFocus?.isConnected)returnFocus.focus();}});});
    window.addEventListener('hashchange',()=>{closeDialogs();requestAnimationFrame(updateCounters);});
  }
  updateCounters();return {openSearch,openBag,refresh:updateCounters};
}





